IF FirstScan THEN
    FT_10_Scaled      := 0.0;
    FT_11_Scaled      := 0.0;
    FIC_10_Integral   := 0.0;
    FIC_11_Integral   := 0.0;
    FIC_10_Output     := 0.0;
    FIC_11_Output     := 0.0;
    FT_10_HH_Active   := FALSE;
    FT_10_LL_Active   := FALSE;
    FT_11_HH_Active   := FALSE;
    FT_11_LL_Active   := FALSE;
    Fv_3_3040_Out     := 6554;
    Fv_3_3041_Out     := 6554;
    ISA_SV_3040       := FALSE;
    ISA_SV_3041       := FALSE;
    FirstScan         := FALSE;
    RETURN;
END_IF;

FT_10_Scaled := ((INT_TO_REAL(FT_10_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;
FT_11_Scaled := ((INT_TO_REAL(FT_11_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;

(* FT-10 HH latch: set when above HH_SP, clear only on ack AND value returned below threshold *)
IF FT_10_Scaled >= FT_10_HH_SP THEN
    FT_10_HH_Active := TRUE;
ELSIF FT_10_HH_Ack AND (FT_10_Scaled <= (FT_10_HH_SP - FT_10_Deadband)) THEN
    FT_10_HH_Active := FALSE;
END_IF;

(* FT-10 H alarm with deadband *)
IF FT_10_Scaled >= FT_10_H_SP THEN
    FT_10_H := TRUE;
ELSIF FT_10_Scaled <= (FT_10_H_SP - FT_10_Deadband) THEN
    FT_10_H := FALSE;
END_IF;

(* FT-10 L alarm with deadband *)
IF FT_10_Scaled <= FT_10_L_SP THEN
    FT_10_L := TRUE;
ELSIF FT_10_Scaled >= (FT_10_L_SP + FT_10_Deadband) THEN
    FT_10_L := FALSE;
END_IF;

(* FT-10 LL latch: set when below LL_SP, clear only on ack AND value returned above threshold *)
IF FT_10_Scaled <= FT_10_LL_SP THEN
    FT_10_LL_Active := TRUE;
ELSIF FT_10_LL_Ack AND (FT_10_Scaled >= (FT_10_LL_SP + FT_10_Deadband)) THEN
    FT_10_LL_Active := FALSE;
END_IF;

(* FT-11 HH latch *)
IF FT_11_Scaled >= FT_11_HH_SP THEN
    FT_11_HH_Active := TRUE;
ELSIF FT_11_HH_Ack AND (FT_11_Scaled <= (FT_11_HH_SP - FT_11_Deadband)) THEN
    FT_11_HH_Active := FALSE;
END_IF;

(* FT-11 H alarm with deadband *)
IF FT_11_Scaled >= FT_11_H_SP THEN
    FT_11_H := TRUE;
ELSIF FT_11_Scaled <= (FT_11_H_SP - FT_11_Deadband) THEN
    FT_11_H := FALSE;
END_IF;

(* FT-11 L alarm with deadband *)
IF FT_11_Scaled <= FT_11_L_SP THEN
    FT_11_L := TRUE;
ELSIF FT_11_Scaled >= (FT_11_L_SP + FT_11_Deadband) THEN
    FT_11_L := FALSE;
END_IF;

(* FT-11 LL latch *)
IF FT_11_Scaled <= FT_11_LL_SP THEN
    FT_11_LL_Active := TRUE;
ELSIF FT_11_LL_Ack AND (FT_11_Scaled >= (FT_11_LL_SP + FT_11_Deadband)) THEN
    FT_11_LL_Active := FALSE;
END_IF;

(* FIC-10 PI controller for upper feed line *)
FIC_10_Error    := FT_10_SP - FT_10_Scaled;
FIC_10_Integral := FIC_10_Integral + (FIC_10_Ki * FIC_10_Error);
IF FIC_10_Integral > 100.0 THEN
    FIC_10_Integral := 100.0;
ELSIF FIC_10_Integral < 0.0 THEN
    FIC_10_Integral := 0.0;
END_IF;
FIC_10_Output := (FIC_10_Kp * FIC_10_Error) + FIC_10_Integral;
IF FIC_10_Output > 100.0 THEN
    FIC_10_Output := 100.0;
ELSIF FIC_10_Output < 0.0 THEN
    FIC_10_Output := 0.0;
END_IF;
Fv_3_3040_Out := REAL_TO_INT(6554.0 + (FIC_10_Output / 100.0) * (32767.0 - 6554.0));

(* Instrument air solenoid open only when no HH or LL alarm active on upper line *)
ISA_SV_3040 := NOT FT_10_HH_Active AND NOT FT_10_LL_Active;

(* FIC-11 PI controller for lower feed line *)
FIC_11_Error    := FT_11_SP - FT_11_Scaled;
FIC_11_Integral := FIC_11_Integral + (FIC_11_Ki * FIC_11_Error);
IF FIC_11_Integral > 100.0 THEN
    FIC_11_Integral := 100.0;
ELSIF FIC_11_Integral < 0.0 THEN
    FIC_11_Integral := 0.0;
END_IF;
FIC_11_Output := (FIC_11_Kp * FIC_11_Error) + FIC_11_Integral;
IF FIC_11_Output > 100.0 THEN
    FIC_11_Output := 100.0;
ELSIF FIC_11_Output < 0.0 THEN
    FIC_11_Output := 0.0;
END_IF;
Fv_3_3041_Out := REAL_TO_INT(6554.0 + (FIC_11_Output / 100.0) * (32767.0 - 6554.0));

(* Instrument air solenoid open only when no HH or LL alarm active on lower line *)
ISA_SV_3041 := NOT FT_11_HH_Active AND NOT FT_11_LL_Active;

(* Aggregate all alarm states for SCADA/HMI *)
System_Alarm :=
    FT_10_HH_Active OR FT_10_LL_Active OR FT_10_H OR FT_10_L OR
    FT_11_HH_Active OR FT_11_LL_Active OR FT_11_H OR FT_11_L;
